describe('Modal Dialog Scroll Behavior', () => {
    beforeEach(() => {
        cy.visit('/your-page-url'); // Replace with the actual URL of the page
        cy.get('.open-modal-button').click(); // Replace with the actual selector to open the modal
    });

    it('should not allow the background page to scroll when the modal is open', () => {
        cy.get('body').should('have.css', 'overflow', 'hidden'); // Check if body overflow is hidden
        cy.get('.modal').should('be.visible'); // Ensure the modal is visible
    });

    it('should allow the background page to scroll when the modal is closed', () => {
        cy.get('.close-modal-button').click(); // Replace with the actual selector to close the modal
        cy.get('body').should('not.have.css', 'overflow', 'hidden'); // Check if body overflow is not hidden
    });
});
